[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    [HttpGet]
    public IActionResult GetAll() => Ok(new[] { "Laptop", "Phone" });

    [HttpGet("{id}")]
    public IActionResult GetById(int id) => Ok($"Product {id}");

    [HttpPost]
    public IActionResult Create([FromBody] Product product)
    {
        return CreatedAtAction(nameof(GetById), new { id = 1 }, product);
    }
}

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    [HttpGet("active")]
    public IActionResult GetActive() => Ok("Active orders");

    [HttpGet("{id:int}")]
    public IActionResult GetById(int id) => Ok($"Order {id}");

    [HttpGet("{year:int:min(2020)}/{month:int:range(1,12)}")]
    public IActionResult GetByDate(int year, int month)
        => Ok($"{year}-{month:D2}");

    [HttpGet("{slug:alpha}")]
    public IActionResult GetBySlug(string slug) => Ok(slug);
}
